#!/bin/sh
set -eu

INFERSTACK_HOME=${INFERSTACK_HOME:-/opt/inferstack}

if [ "$(id -u)" -ne 0 ]; then
  echo "ERROR: run as root" >&2
  exit 1
fi
PAYLOAD_SHA256=3a571f1de56db7d72ab28d44fa427879555f396bc3059e2d6d17aae8c4574a83
PAYLOAD_B64=""

workdir=$(mktemp -d)
trap 'rm -rf "$workdir"' EXIT

printf '%s' "$PAYLOAD_B64" | base64 -d > "$workdir/inferstack.tgz"

actual=$(sha256sum "$workdir/inferstack.tgz" | cut -d' ' -f1)
if [ "$actual" != "$PAYLOAD_SHA256" ]; then
  echo "ERROR: payload checksum mismatch - download corrupted" >&2
  exit 1
fi

mkdir -p "$INFERSTACK_HOME/log"
tar xzf "$workdir/inferstack.tgz" --strip-components=1 -C "$INFERSTACK_HOME"

say() {
  echo "$1"
  echo "$1" >> "$INFERSTACK_HOME/log/install.log"
}

say "install start $(date -u +%FT%TZ)"
say "payload: checksum ok"
say "tree: extracted to $INFERSTACK_HOME"

mkdir -p /etc/docker
result=$(python3 - <<'PY'
import json
path = "/etc/docker/daemon.json"
try:
    cfg = json.load(open(path))
except Exception:
    cfg = {}
wanted = {
    "bip": "172.31.0.1/24",
    "default-address-pools": [{"base": "172.31.128.0/17", "size": 24}],
}
changed = False
for key, value in wanted.items():
    if cfg.get(key) != value:
        cfg[key] = value
        changed = True
json.dump(cfg, open(path, "w"), indent=2)
print("CHANGED" if changed else "OK")
PY
)
if [ "$result" = CHANGED ]; then
  if command -v docker >/dev/null 2>&1; then
    systemctl restart docker
    say "docker pools: applied, docker restarted"
  else
    say "docker pools: set for first docker start"
  fi
else
  say "docker pools: unchanged"
fi

exec "$INFERSTACK_HOME/tools/deploy.sh"
